package com.posgateway.aml.entity.audit;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import org.hibernate.envers.RevisionEntity;
import org.hibernate.envers.RevisionNumber;
import org.hibernate.envers.RevisionTimestamp;

import java.io.Serializable;
import java.util.Objects;

/**
 * Envers revision entity mapped exactly onto the {@code revinfo} table created by migration V120
 * ({@code rev INTEGER GENERATED BY DEFAULT AS IDENTITY}, {@code revtstmp BIGINT}).
 *
 * <p>Without this class Envers falls back to {@code DefaultRevisionEntity}, whose
 * {@code @GeneratedValue} resolves to a pooled {@code revinfo_seq} sequence (allocation 50) that no
 * migration creates — every audited write on a fresh database then failed with
 * {@code relation "revinfo_seq" does not exist}. Using the identity column the schema already has
 * removes the sequence dependency entirely (no allocation-size drift between Hibernate and the DB)
 * and, because {@code DefaultRevisionEntity} is no longer a managed type, also removes the
 * HHH015007 static-metamodel error logged at boot.
 */
@Entity
@Table(name = "revinfo")
@RevisionEntity
public class AuditRevisionEntity implements Serializable {

    private static final long serialVersionUID = 1L;

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @RevisionNumber
    @Column(name = "rev")
    private int rev;

    @RevisionTimestamp
    @Column(name = "revtstmp")
    private long revtstmp;

    /** Revision number assigned by the database identity column. */
    public int getRev() {
        return rev;
    }

    /** Sets the revision number (used by Hibernate only). */
    public void setRev(int rev) {
        this.rev = rev;
    }

    /** Revision commit time in epoch milliseconds. */
    public long getRevtstmp() {
        return revtstmp;
    }

    /** Sets the revision timestamp (used by Envers only). */
    public void setRevtstmp(long revtstmp) {
        this.revtstmp = revtstmp;
    }

    /** Identity is the revision number. */
    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof AuditRevisionEntity other)) {
            return false;
        }
        return rev == other.rev && revtstmp == other.revtstmp;
    }

    /** Consistent with {@link #equals(Object)}. */
    @Override
    public int hashCode() {
        return Objects.hash(rev, revtstmp);
    }
}
